-- Appended after the intake fixture; isolated transaction rolls back every transition.
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
UPDATE public.appointment SET staff_id='20000000-0000-0000-0000-000000000002' WHERE id='70000000-0000-0000-0000-000000000001';
SELECT set_config('handover.version',(SELECT updated_at::text FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),true);
SELECT set_config('handover.payments',(SELECT count(*)::text FROM public.payment),true);
SET LOCAL ROLE authenticated;
SELECT set_config('handover.session',public.prepare_handover_media_upload(gen_random_uuid(),'70000000-0000-0000-0000-000000000001','82000000-0000-0000-0000-000000000001',100,'image/png','handover.png')->>'session_id',true);
SELECT set_config('handover.lease',public.claim_media_upload(current_setting('handover.session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('handover.asset',public.finish_media_upload(current_setting('handover.session')::uuid,current_setting('handover.lease')::uuid,'10000000-0000-0000-0000-000000000002',repeat('6',64),2,2)::text,true);
RESET ROLE;
SELECT set_config('handover.details',jsonb_build_object('qualityAccepted',true,'belongingsReturned',true,'customerConfirmed',true,'media_asset_ids',jsonb_build_array(current_setting('handover.asset')))::text,true);
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect_error($q$SELECT public.save_admin_service_record('82000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000001',current_setting('handover.version')::timestamptz,'handover',current_setting('handover.details')::jsonb)$q$,'42501');
SELECT pg_temp.expect_error($q$SELECT public.save_admin_service_record('82000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('handover.version')::timestamptz,'handover',jsonb_set(current_setting('handover.details')::jsonb,'{media_asset_ids}',jsonb_build_array(current_setting('intake.asset'))))$q$,'42501');
SELECT pg_temp.expect_error($q$SELECT public.save_admin_service_record('82000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('handover.version')::timestamptz,'handover',jsonb_set(current_setting('handover.details')::jsonb,'{customerConfirmed}','false'))$q$,'22023');
RESET ROLE;
SELECT pg_temp.assert((SELECT appointment_status='in_progress' FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),'invalid handover image rolls back completion');
SET LOCAL ROLE authenticated;
SELECT public.save_admin_service_record('82000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('handover.version')::timestamptz,'handover',current_setting('handover.details')::jsonb);
SELECT public.save_admin_service_record('82000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',current_setting('handover.version')::timestamptz,'handover',current_setting('handover.details')::jsonb);
SELECT pg_temp.assert(jsonb_array_length(public.list_handover_media('70000000-0000-0000-0000-000000000001'))=1,'handover retry one reference');
SELECT pg_temp.assert(jsonb_array_length(public.list_intake_media('70000000-0000-0000-0000-000000000001'))=1,'intake gallery preserved separately');
RESET ROLE;
SELECT pg_temp.assert((SELECT appointment_status='completed' FROM public.appointment WHERE id='70000000-0000-0000-0000-000000000001'),'valid handover completes appointment');
SELECT pg_temp.assert((SELECT count(*)::text=current_setting('handover.payments') FROM public.payment),'handover creates no payment');
SELECT pg_temp.assert((SELECT legal_hold AND status='attached' FROM public.media_asset WHERE id=current_setting('handover.asset')::uuid),'handover evidence held');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('handover.asset')::uuid) IS NOT NULL,'owner reads handover evidence');
SELECT pg_temp.assert(jsonb_array_length(public.list_handover_media('70000000-0000-0000-0000-000000000001'))=1,'owner lists handover');
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('handover.asset')::uuid) IS NULL,'wrong customer denied');
SELECT pg_temp.expect_error($q$SELECT public.list_handover_media('70000000-0000-0000-0000-000000000001')$q$,'42501');
RESET ROLE;
UPDATE public.appointment SET staff_id=null WHERE id='70000000-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('handover.asset')::uuid) IS NULL,'revoked staff denied handover');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('handover.asset')::uuid) IS NULL,'handover never public');
RESET ROLE;
